-- BJ001: 莉莉 — 流浪狗妈妈，昌平区被救助
INSERT INTO animal (animal_no, name, category, sex, body_size, age, avatar, is_sterilized, activity_scope, status, description, detail_content, location, latitude, longitude) VALUES
('BJ001', '莉莉', 'DOG', 'FEMALE', 'MEDIUM', 11, 'https://www.pohome.cn/upload/img/pet/avatar/large/175746080483313953.jpeg', 1, '北京', 1, '莉莉性格胆小谨慎，需要比较长的时间和耐心来磨合。已免疫、已绝育。', '<p>流浪狗在城市里的生存空间非常有限，自己流浪，翻翻垃圾桶还能找点东西吃，但生了小baby的狗狗想要活下去就更难了。莉莉就是这样一个流浪狗妈妈，它本性格温顺安静，被遗弃在北京昌平区的一个小区里，自从生了一窝小狗，就开始了日复一日地遭人厉喝驱赶的日子。莉莉为了保护自己的孩子，变得不再温顺，在艰难的寻找安全落脚点的过程中，3个孩子只剩下了1个。狗妈莉莉每天顽强地对抗着全世界，直到被志愿者救起，莉莉一直处于戒备状态。</p><figure class="image"><img src="https://www.pohome.cn/upload/img/blog/content/175746067329452320.png"></figure><p>被救助后的生活逐渐稳定下来，再加上孩子的陪伴，莉莉开始慢慢地重新和人类建立感情，越来越亲人，越来越多互动。但是对于想要领养莉莉的家庭，我们有个小小的私心，希望莉莉能和它的孩子"淘淘"一起被领养，让它和孩子不再分离。</p>', '北京市昌平区某小区', 39.9042, 116.4074);

-- BJ002: 巴豆 — 右前腿曾受伤坏死，垃圾桶旁被发现
INSERT INTO animal (animal_no, name, category, sex, body_size, age, avatar, is_sterilized, activity_scope, status, description, detail_content, location, latitude, longitude) VALUES
('BJ002', '巴豆', 'DOG', 'MALE', 'MEDIUM', 9, 'https://www.pohome.cn/upload/img/pet/avatar/large/175653768091142236.jpeg', 1, '北京', 1, '巴豆已免疫、已绝育，性格亲人活泼，右前腿曾受伤坏死，但完全不影响正常生活。', '<p>我们与巴豆的第一次见面是在2016年秋天，它只有3个月大，还是个毛绒绒的小朋友，坐在垃圾桶旁边哼哼唧唧地哭着，右前腿有血迹，伤口已经结痂，志愿者目测被车撞伤的可能性很大，送到医院进行检查后医生的诊断是：右前腿坏死，终身残疾。</p><p>在医院完成了全套的治疗、驱虫、免疫和绝育后，小巴豆开始了集体生活。一晃5年过去了，巴豆长成一个大姑娘，没有所谓高贵的血统、迷你的体型，只是个普普通通的中华田园犬，但巴豆有温顺的性格和好身体。它已经习惯了右前腿的小问题，可以正常地走路和跑跳，一点都不碍事。将来巴豆的领养人只要每年定期带它去医院做个小体检就可以了，其实照顾一只略有残疾的狗狗也并不是什么费劲的事，反而更有意义，不是吗？</p><figure class="image"><img src="https://www.pohome.cn/upload/img/blog/content/175653743840987227.png"></figure>', '北京市朝阳区某小区垃圾桶旁', 39.9042, 116.4074);

-- BJ003: 黑金 — 被开车扔到小区，后腿被打伤，康复后爱奔跑
INSERT INTO animal (animal_no, name, category, sex, body_size, age, avatar, is_sterilized, activity_scope, status, description, detail_content, location, latitude, longitude) VALUES
('BJ003', '黑金', 'DOG', 'MALE', 'MEDIUM', 2, 'https://api.dicebear.com/9.x/avataaars/svg?seed=heijin_dog', 1, '北京', 1, '黑金性格害羞但亲人，后腿曾受伤，现已康复，特别爱跑步。已免疫、已绝育。', '<p>黑金大约在3个月大的时候，被一个开车的人扔到了北京的一个小区里，从此开始了流浪生活。一个还没断奶的小奶狗，突然失去了所有的庇护，只能蜷缩在小区的角落里等待命运的判决。</p><p>更令人心痛的是，它在小区流浪时被不喜欢狗狗的人打伤了腰部和后腿，被发现时走路一瘸一拐。送到医院后，医生判断它的左后腿可能在小时候经历过车祸或重击，导致骨骼错位愈合。但黑金的求生意志非常顽强，经过长时间的治疗和休养，它不但恢复了健康，还展现出了惊人的活力——它特别爱跑步！在领养中心的院子里，黑金跑起来像一阵黑色的旋风，完全看不出曾经受过那么重的伤。</p><p>黑金性格慢热，初次见面时有些害羞，但一旦建立了信任，它会用最温柔的眼神看着你，把头轻轻靠在你腿上。它需要一个有耐心的家庭，给它时间去重新相信人类。一旦它认定了你，你会收获这世界上最忠诚的陪伴。</p>', '北京市丰台区某小区', 39.9042, 116.4074);

-- BJ004: 双喜 — 被热油烫伤，经过一年治疗康复
INSERT INTO animal (animal_no, name, category, sex, body_size, age, avatar, is_sterilized, activity_scope, status, description, detail_content, location, latitude, longitude) VALUES
('BJ004', '双喜', 'DOG', 'FEMALE', 'MEDIUM', 5, 'https://api.dicebear.com/9.x/avataaars/svg?seed=shuangxi_dog', 1, '北京', 1, '双喜性格亲人又赖皮，曾被人用热油烫伤，经过一年治疗完全康复。已免疫、已绝育。', '<p>双喜的遭遇让人不忍卒读。志愿者从网上获知消息后，在北京南四环大红门附近找到了它——一只"看不清模样的狗"。它的脸和身上患有严重的皮肤病，更让人愤怒的是，它的脖子和后背被人恶意用热油烫伤，皮肤大面积溃烂，散发着刺鼻的气味。没有人知道它经历了什么样的噩梦。</p><p>双喜被紧急纳入汪汪喵呜孤儿院"小天使基金"救助项目，编号3号。治疗过程漫长而艰难——清创、换药、抗感染、促进皮肤再生……每一步都是对双喜和医护人员的考验。但双喜表现得无比坚强，每次换药都安安静静地配合，仿佛知道这些人在帮它。经过长达一年的治疗和康复，双喜的恢复情况比大夫预期的还要好，新生的皮肤虽然留下了疤痕，但它重新变回了一只漂亮的狗狗。</p><p>也许是经历过最黑暗的时刻，双喜格外珍惜现在的生活。它性格如其名——亲人又赖皮，最喜欢的事就是蹭在志愿者脚边求摸摸。它非常聪明，能感受到人的情绪，当你难过的时候它会安静地趴在你身边；当你开心的时候它会摇着尾巴围着你转圈。经历了那么多苦难，双喜依然选择相信人类，这是一份无比珍贵的信任。</p>', '北京市丰台区大红门附近', 39.9042, 116.4074);

-- BJ005: 小66 — 脖子上被缠满铁丝电线，奇迹生还
INSERT INTO animal (animal_no, name, category, sex, body_size, age, avatar, is_sterilized, activity_scope, status, description, detail_content, location, latitude, longitude) VALUES
('BJ005', '小66', 'DOG', 'MALE', 'SMALL', 4, 'https://api.dicebear.com/9.x/avataaars/svg?seed=xiao66_dog', 1, '北京', 1, '小66曾遭遇严重虐待，脖子上被缠满铁丝和电线，现已完全康复。性格温和亲人，已免疫、已绝育。', '<p>救助人第一次在小区楼下看到小66时，远远望去以为它脖子上戴着一个红色的项圈，还以为是只有主人的狗。直到某天早晨近距离接触时才发现——那根本不是项圈！小66的脖子上被人缠满了一圈又一圈的铁丝、电线、塑料绳、自行车锁铁丝，脖子上的肉有一半都被勒烂了，血肉模糊，散发着腐肉的恶臭。铁丝被人恶意紧了又紧，塑料绳已经烂在了肉里。它每次呼吸、每次吞咽，都是在承受着难以想象的痛苦。</p><p>救助过程也是一场持久战。小66非常警觉，一叫就跑，难以接近。救助人连续多天深夜带着鸡蛋、肉干下楼找它，只为"混个脸熟"。转机发生在2016年6月22日——救助人用一盒涮羊肉成功吸引了它。吃完肉后，小66突然围着救助人呜呜地哭了起来，在她脚边绕来绕去，仿佛在诉说这些年的委屈。</p><p>送到医院时，小66发烧39.6℃，医生费了很大功夫才将脖子上的各种铁丝、电线、塑料绳一一剪开。令人心疼的是，从头到尾它没有反抗过一次，十分配合治疗，好像知道这些人终于来救它了。如今的小66已经完全康复，虽然脖子上留下了永久的疤痕，但它的心已经被爱治愈。它非常温和亲人，喜欢和人待在一起，是一只让人心疼又敬佩的小狗。</p>', '北京市通州区某小区', 39.9042, 116.4074);

