-- BJ006: 警长 — 天通苑超市门口"碰瓷"抱大腿的猫咪
INSERT INTO animal (animal_no, name, category, sex, body_size, age, avatar, is_sterilized, activity_scope, status, description, detail_content, location, latitude, longitude) VALUES
('BJ006', '警长', 'CAT', 'MALE', 'SMALL', 7, 'https://www.pohome.cn/upload/img/pet/avatar/large/175746027657365791.jpeg', 1, '北京', 1, '警长身材苗条匀称，活力四射，已免疫、已绝育。', '<p>捡猫奇遇记</p><p>救助小警长纯属意外，可以说是小警长在主动自救。</p><figure class="image"><img src="https://www.pohome.cn/upload/img/blog/content/175746012948990238.png"></figure><p>2019年冬天，救助人本是去北京天通苑的一家物美超市买菜的，买完菜一出超市大门口，就被不明物体冲过来一把抱住了大腿，然后就顺着裤腿往身上爬。讲真，救助人当时还真是被吓了一大跳。低头一看，原来是只2个月左右的小猫咪，喵喵叫着抓住救助人的裤子不放手，一副认真求助、一定要让人把它带回家的模样，恐怕这就是传说中的"被猫选中了"。救助人只好一手拎着菜兜子，一手抱着猫回家。</p><p>小警长身材苗条，细胳膊细腿小瘦脸，是北方很少见的体型，像暹罗猫，性格也像，活泼好动，好奇心强，跟熟悉的人非常亲近。</p>', '北京市昌平区天通苑物美超市', 39.9042, 116.4074);

-- BJ007: 翠花 — 顺义樱花园的"花臂大佬"，人工合成"折耳猫"
INSERT INTO animal (animal_no, name, category, sex, body_size, age, avatar, is_sterilized, activity_scope, status, description, detail_content, location, latitude, longitude) VALUES
('BJ007', '翠花', 'CAT', 'FEMALE', 'SMALL', 10, 'https://www.pohome.cn/upload/img/pet/avatar/large/175745987330181405.jpeg', 1, '北京', 1, '翠花的左耳发生了耳血肿，反复做了2次手术，手术后的翠花变成了人工合成"折耳猫"，已免疫、已绝育。', '<p>翠花，是个漂亮的三花猫，也可以被称为"花臂大佬"。2016年春，汪喵志愿者在北京顺义樱花园小区进行的流浪猫TNR（抓捕-绝育-放归）项目时，遇见了半岁大的翠花。虽然它是个流浪二代，但它表现得非常亲人，送到医院做完绝育之后，又进行了体检、驱虫和免疫，留在猫屋准备找领养试试看。</p><figure class="image"><img src="https://www.pohome.cn/upload/img/blog/content/175745980802533660.png"></figure><p>去年，翠花的左耳发生了耳血肿，反复做了2次手术，手术后的翠花变成了人工合成"折耳猫"。</p><p>翠花跟其它猫咪相处融洽，好奇心非常强，爱探索新世界，喜欢吃罐头和肉肉，不喜欢被抱，与人为善但不是很粘人那一款哦。</p>', '北京市顺义区樱花园小区', 39.9042, 116.4074);

-- BJ008: 大白 — 猫屋老住户，蓝眼白毛，与世无争
INSERT INTO animal (animal_no, name, category, sex, body_size, age, avatar, is_sterilized, activity_scope, status, description, detail_content, location, latitude, longitude) VALUES
('BJ008', '大白', 'CAT', 'MALE', 'SMALL', 19, 'https://www.pohome.cn/upload/img/pet/avatar/large/175745508647635222.jpeg', 1, '北京', 1, '大白是猫屋里的老住户，一双迷人的浅蓝色眼睛，一身雪白的大长毛，与世无争。已免疫、已绝育。', '<p>大白是猫屋里的老住户了，一双迷人的浅蓝色眼睛，一身雪白的大长毛，想当年可以说是老北京人的最爱！</p><figure class="image"><img src="https://www.pohome.cn/upload/img/blog/content/175745494700263701.png"></figure><p>2013年，大白的原主人全家南迁，原主人把家里养的4只大猫一起遗弃了。长期在室内生活的家猫根本没有户外生存能力，突然的环境改变和无处觅食导致其中两只猫急性肾衰，后来都回喵星了。大白和弟弟小多跟着志愿者去了医院，左后腿因为血液病问题导致脚趾坏死，手术摘除了一个脚趾头，输液20多天后顺利出院，开始了集体生活。</p><p>大白很爱护弟弟小多，在猫屋这种多猫环境里，难免会有喵星人互相看着不顺眼而闹矛盾。每次小多被其它猫欺负了，大白都会马上冲过去帮忙，当然最后很可能是兄弟俩一起被打，还要铲屎官来调解维和。</p><p>大白性格温和亲人，老成稳定，每天吃喝完毕就晒太阳睡觉，可乖了。</p>', '北京市朝阳区（原主人遗弃）', 39.9042, 116.4074);

-- BJ009: 吉祥 — 超市门口救助的重症膈疝猫，奇迹生还
INSERT INTO animal (animal_no, name, category, sex, body_size, age, avatar, is_sterilized, activity_scope, status, description, detail_content, location, latitude, longitude) VALUES
('BJ009', '吉祥', 'CAT', 'MALE', 'SMALL', 5, 'https://api.dicebear.com/9.x/avataaars/svg?seed=jixiang_cat', 1, '北京', 1, '吉祥曾患严重膈疝和口腔炎，经历大手术后奇迹康复。性格温柔粘人，已免疫、已绝育。', '<p>吉祥的故事是一个关于生命力与奇迹的故事。一位好心人在超市门口发现了这只奄奄一息的猫咪——它瘦得皮包骨头，嘴里流着黄色的脓水，呼吸困难，连抬头的力气都快没有了。送到医院一检查，所有人都倒吸一口凉气：严重膈疝——两侧膈膜破裂，肠子压迫心脏，右侧肺部几乎看不到，胃下垂，肾脏被向后挤压；同时还患有严重的口腔炎，嘴里全部溃烂。</p><p>医生坦言，这种情况能活下来的概率很低。但吉祥表现出了惊人的求生意志。在确诊后的第二天，它就开始少量进食；第三天能吃小米粥了，还能自主排便。救助团队决定为它争取一次机会。手术持续了几个小时，医生小心翼翼地将它移位的脏器一一复位。手术成功了，但术后48小时的观察期才是真正的鬼门关。</p><p>那两天里，志愿者轮流守在吉祥身边，不敢合眼。而吉祥也用它的方式回应着——术后第一天，它就挣扎着站起来溜达了几步，仿佛在说"我想活下去"。吉祥真的活了！如今它已经完全康复，性格温柔粘人，喜欢趴在人的腿上打呼噜。从鬼门关走了一遭的吉祥，格外珍惜现在平静温暖的生活，它会用最轻柔的咕噜声来告诉你：谢谢你没有放弃我。</p>', '北京市海淀区某超市门口', 39.9042, 116.4074);

-- BJ010: 妙妙 — 断尾橘猫，走失4年跨越400公里回家
INSERT INTO animal (animal_no, name, category, sex, body_size, age, avatar, is_sterilized, activity_scope, status, description, detail_content, location, latitude, longitude) VALUES
('BJ010', '妙妙', 'CAT', 'FEMALE', 'SMALL', 3, 'https://api.dicebear.com/9.x/avataaars/svg?seed=miaomiao_cat', 1, '北京', 1, '妙妙是一只橘猫，尾巴曾被夹断，性格独立又亲人。经历传奇——走失4年后奇迹般回到救助人身边。已免疫、已绝育。', '<p>妙妙是一只橘色的小母猫，最初被救助时尾巴被夹断了，这是它身上最明显的特征。它性格独立，有点女王范儿，但在信任的人面前又会变得格外粘人。在救助站生活期间，妙妙被一位山东的领养人领养，大家都以为它会从此过上幸福安稳的生活。</p><p>然而命运给妙妙开了一个残酷的玩笑。2019年春节，妙妙从新家的门缝里跑了出去，从此杳无音信。领养人找了很久都没有找到，这成了所有人心中的一根刺。四年过去了，没有人想到还能再见到妙妙。</p><p>奇迹发生在四年后的一个普通傍晚。原救助人出门倒垃圾时，被一只橘猫拦住了去路。因为没戴眼镜，以为是自家猫，就顺手提回了家。第二天仔细一看，这只猫的尾巴有断裂的旧痕，救助人心里咯噔一下，试探性地叫了一声"妙妙"——那只猫竟然回头了！救助人不敢相信，又试着发出之前训练过的口令，猫咪竟然一一照做。这就是妙妙！四年了，从山东菏泽到北京，跨越400多公里，谁也不知道它是怎么找回来的。也许在妙妙的心里，救助人最初给它的那个临时的家，才是它认定的真正的家。妙妙用四年时间证明了一件事：有些羁绊，时间和距离都无法切断。</p>', '北京市海淀区', 39.9042, 116.4074);

